import hashlib, random
from dataclasses import dataclass

@dataclass
class Replica:
    url: str
    queued_tokens: int = 0   # prompt + expected output tokens waiting (scraped)
    kv_usage: float = 0.0    # 0..1 KV-cache utilization (scraped)
    healthy: bool = True     # active probe + outlier ejection

def load(r: Replica) -> float:
    # Near-full KV cache means preemptions soon: penalize it hard
    return r.queued_tokens * (1 + 10 * max(0.0, r.kv_usage - 0.9))

def home_for(prefix: str, live: list[Replica]) -> Replica:
    # Rendezvous hashing: same prefix -> same replica; few keys move on churn
    return max(live, key=lambda r: hashlib.sha1(f"{r.url}|{prefix}".encode()).digest())

def pick(replicas: list[Replica], prompt: str, slack: float = 1.5) -> Replica:
    live = [r for r in replicas if r.healthy]
    home = home_for(prompt[:4000], live)   # system prompt + early turns
    a, b = random.sample(live, 2) if len(live) > 1 else (live[0], live[0])  # P2C
    best = min(a, b, key=load)
    # Prefer the cache hit unless home is clearly busier than a random alternative
    return home if load(home) <= slack * load(best) + 1000 else best
